type CourseTeaching = { about: string; basics: string; logic: string; project: string; basicsTask: string; logicTask: string; projectTask: string; check: [string, string, string, string] };

// Each path starts with a plain-language explanation and then introduces its own real foundations.
const courseTeaching: Record<string, CourseTeaching> = {
  javascript: { about:"JavaScript ist eine dynamische Programmiersprache. Browser führen sie mit einer JavaScript-Engine aus; mit Node.js läuft sie auch auf dem Server oder in Werkzeugen. Webseiten nutzen sie für Reaktionen auf Klicks, Formulare und Daten. JavaScript ist standardisiert (ECMAScript); Browser-APIs wie das DOM gehören zur Browserumgebung, nicht zur Sprache selbst.", basics:"Ein Name wie const score = 12 speichert einen Wert für spätere Schritte. Texte (string), Zahlen (number) und Wahrheitswerte (boolean) sind unterschiedliche Datentypen. const verhindert eine neue Zuweisung an den Namen; bei let ist sie möglich. Ein Objekt gruppiert benannte Eigenschaften, ein Array mehrere geordnete Werte.", logic:"if/else wählt einen Weg anhand einer Bedingung. Schleifen wiederholen Arbeit. Funktionen bündeln Schritte, nehmen Parameter entgegen und können mit return ein Ergebnis liefern. Im Browser lösen Ereignisse wie click Funktionen aus; document.querySelector und addEventListener sind Browser-APIs.", project:"Ein kleines Browserprojekt kann Eingaben aus einem Formular lesen, sie prüfen und eine Rückmeldung anzeigen. Trenne Daten, Prüfung und Darstellung in kleine Funktionen. React ist ein UI-Framework für Komponenten; es baut auf JavaScript auf und ist kein Ersatz für die Grundlagen.", basicsTask:"Ergänze das Beispiel um eine eigene const-Variable für deinen Lernstatus und gib sowohl Name als auch Status mit console.log aus.", logicTask:"Erweitere die Punkteprüfung um einen zweiten Fall (unter 10) und gib für beide Fälle unterschiedliche Meldungen aus.", projectTask:"Mini-Projekt: Schreibe eine Funktion, die eine Punktzahl annimmt, und ein Browserereignis, das das Ergebnis nach einem Klick anzeigt. Prüfe zusätzlich eine ungültige Eingabe.", check:["Was führt JavaScript im Browser aus?","Die JavaScript-Engine des Browsers führt den Sprachcode aus.","CSS führt JavaScript aus.","JavaScript kann nur in einem bestimmten Browser laufen."] },
  java: { about:"Java ist eine statisch typisierte, klassenbasierte Sprache. Der Compiler übersetzt Quelltext in Bytecode; die Java Virtual Machine (JVM) führt ihn aus. Java wird unter anderem für Server, Unternehmenssoftware und Desktopprogramme eingesetzt. JDK enthält Compiler und Werkzeuge; die JVM ist die Laufzeit.", basics:"Vor einer Variablen steht meist ihr Typ: int für ganze Zahlen, double für Kommazahlen, boolean für wahr/falsch und String für Text. Eine Zuweisung wie int score = 12 legt einen Namen und Wert fest. Java prüft viele Typfehler bereits beim Kompilieren.", logic:"if/else und Schleifen steuern den Ablauf. Methoden bündeln Code; Parameter sind Eingaben, ein Rückgabetyp beschreibt das Ergebnis. Klassen definieren eigene Typen und verbinden Zustand (Felder) mit Verhalten (Methoden). Eine main-Methode dient häufig als Programmeinstieg.", project:"Baue ein kleines Punkteprogramm mit einer Klasse, einer Methode zur Bewertung und klaren Eingabegrenzen. JUnit ist ein Testframework für Java. Spring Boot hilft beim Bau von Webdiensten, wenn Klassen, Methoden und Typen bereits vertraut sind.", basicsTask:"Erstelle eine int-Variable points und eine String-Variable name. Gib beide mit System.out.println aus und achte auf Groß-/Kleinschreibung bei String.", logicTask:"Schreibe eine if/else-Prüfung: Ab 10 Punkten soll „Bestanden“, darunter „Weiter üben“ erscheinen.", projectTask:"Mini-Projekt: Erstelle eine Methode bewerten(int points), die eine verständliche Meldung zurückgibt. Ergänze je einen Testfall oberhalb und unterhalb der Grenze.", check:["Wie wird typischer Java-Quellcode ausgeführt?","Compiler erzeugt Bytecode, den die JVM ausführt.","Der Browser wandelt Java automatisch in HTML um.","Java braucht grundsätzlich keinen Compiler oder keine Laufzeit."] },
  python: { about:"Python ist eine universelle, hochsprachige Programmiersprache mit einer bewusst lesbaren Syntax. Sie wird für Automatisierung, Webdienste, Datenanalyse und wissenschaftliche Arbeit genutzt. Die verbreitete Implementierung CPython führt kompilierten Bytecode in einer virtuellen Maschine aus; „Python ist nur eine Skriptsprache“ wäre daher zu kurz gegriffen.", basics:"Variablen entstehen durch Zuweisung, etwa name = 'Ada'. Häufige Grundtypen sind int, float, str und bool. Einrückung kennzeichnet Codeblöcke und ist Teil der Syntax. Listen speichern geordnete Werte; Dictionaries ordnen Werte Schlüsseln zu.", logic:"if/elif/else wählt Fälle; for durchläuft Elemente, while wiederholt solange eine Bedingung gilt. def definiert eine Funktion. Parameter übergeben Werte, return gibt ein Ergebnis zurück. Module teilen Programme in Dateien und wiederverwendbare Bestandteile.", project:"Baue ein kleines Auswertungsprogramm mit Eingabeprüfung, Funktion und Liste von Ergebnissen. pytest ist ein Testframework; FastAPI eignet sich für APIs, pandas für tabellarische Daten. Diese Bibliotheken ergänzen Python, ersetzen aber nicht Variablen, Bedingungen und Funktionen.", basicsTask:"Lege name, points und learning als Text-, Zahlen- und Wahrheitswert an. Gib die Werte sowie type(points) aus.", logicTask:"Verwende if/else für die Grenze von 10 Punkten und ergänze anschließend eine for-Schleife, die mehrere Punktwerte prüft.", projectTask:"Mini-Projekt: Schreibe eine Funktion, die eine Liste von Punktzahlen durchläuft und die Anzahl bestandener Werte zurückgibt. Teste eine leere Liste und mehrere Werte.", check:["Was kennzeichnet Python-Codeblöcke?","Einrückung zeigt, welche Anweisungen zu einem Block gehören.","Jede Anweisung muss in geschweiften Klammern stehen.","Python ignoriert Einrückungen immer vollständig."] },
  php: { about:"PHP ist eine Programmiersprache, die besonders häufig auf Webservern läuft. Ein Webserver kann PHP für eine Anfrage ausführen und daraus HTML oder JSON erzeugen. PHP kann auch über die Kommandozeile laufen. Laravel ist ein Framework für Webanwendungen; es ist kein Bestandteil der PHP-Sprache.", basics:"Variablennamen beginnen in PHP mit $. Werte haben Typen wie int, float, string, bool und array. echo gibt Inhalt aus; in einer Webanfrage wird daraus typischerweise Teil der Serverantwort. Benutzereingaben sind zunächst nicht vertrauenswürdig und müssen geprüft werden.", logic:"if/else und foreach steuern Abläufe. Funktionen nehmen Parameter entgegen und können Rückgabetypen angeben. Bei Webformularen verarbeitet der Server Anfrageparameter; Datenbankzugriffe sollten mit vorbereiteten, parametrisierten Abfragen erfolgen, nicht durch Zusammenkleben von SQL-Text.", project:"Ein kleines Kontaktformular verarbeitet eine Anfrage, validiert Felder und zeigt eine sichere Antwort. Laravel bietet Routing, Validierung und Datenbankwerkzeuge. PHPUnit testet PHP-Code. Diese Werkzeuge setzen sichere Grundlagen voraus.", basicsTask:"Ergänze $name und $points mit passenden Werten und gib beide mit echo aus. Erkläre im Kommentar, welche Daten von außen kommen könnten.", logicTask:"Prüfe mit if/else, ob mindestens 10 Punkte erreicht wurden. Ergänze eine Prüfung, die eine negative Punktzahl ablehnt.", projectTask:"Mini-Projekt: Baue eine kleine serverseitige Punkteauswertung mit Funktion und Eingabevalidierung. Beschreibe, warum Formularwerte geprüft werden müssen.", check:["Wo läuft PHP bei einer typischen Webanfrage?","Auf dem Webserver, der daraus eine Antwort erzeugt.","Ausschließlich im CSS-Layout des Browsers.","PHP läuft automatisch in jeder SQL-Datenbank."] },
  typescript: { about:"TypeScript erweitert JavaScript um ein statisches Typsystem. Der TypeScript-Compiler prüft Typen und erzeugt JavaScript; Browser und Node.js führen das erzeugte JavaScript aus. TypeScript-Typen sind normalerweise zur Laufzeit nicht mehr vorhanden. Zod ist dagegen eine Bibliothek, die Daten auch zur Laufzeit validieren kann.", basics:"string, number und boolean beschreiben erwartete Werte. Ein Typ hilft dem Editor und Compiler, widersprüchliche Verwendung früh zu finden. Interfaces und Type-Aliases beschreiben Objektformen. Typannotationen prüfen Code zur Entwicklungszeit, sie ersetzen keine Prüfung externer JSON-Daten.", logic:"Kontrollfluss und Funktionen funktionieren wie in JavaScript, werden aber zusätzlich typgeprüft. Union-Typen erlauben mehrere ausdrücklich benannte Fälle. Generics beschreiben wiederverwendbaren Code, der Typinformationen erhält. DOM und Fetch stammen aus Browser-/Web-APIs, nicht aus TypeScript selbst.", project:"Baue eine kleine Liste typisierter Aufgaben und prüfe API-Antworten an der Systemgrenze. React ist eine UI-Bibliothek, kein Teil von TypeScript. Zod ergänzt Laufzeitvalidierung; erst die Kombination aus Typprüfung und Eingabevalidierung schützt unterschiedliche Fehlerklassen.", basicsTask:"Ergänze name als string und points als number. Prüfe, welchen Fehler der Editor anzeigt, wenn du points versehentlich einen Text zuweist.", logicTask:"Schreibe eine typisierte Funktion, die eine Punktzahl annimmt und für gültige Werte eine Meldung zurückgibt. Behandle negative Eingaben ausdrücklich.", projectTask:"Mini-Projekt: Erstelle einen Type-Alias für ein Ergebnisobjekt und eine Funktion, die es baut. Beschreibe im Kommentar, warum eine API-Antwort trotzdem geprüft werden muss.", check:["Was führt eine Webseite nach dem TypeScript-Build aus?","Das erzeugte JavaScript.","TypeScript-Typen werden im Browser vollständig als eigene Laufzeit benötigt.","TypeScript ersetzt HTML und den Browser."] },
  cpp: { about:"C++ ist eine kompilierte Mehrzwecksprache, die hohe Leistung mit Abstraktionen wie Klassen und der Standardbibliothek verbindet. Ein Compiler übersetzt Quelltext meist in Maschinencode. C++ wird unter anderem in Spielen, Grafik, eingebetteten Systemen und leistungsintensiven Anwendungen eingesetzt. C++ und C sind verwandte, aber unterschiedliche Sprachen.", basics:"Variablen besitzen Typen wie int, double und std::string. std::cout gibt Text aus. Blöcke werden mit geschweiften Klammern geschrieben. Die Standardbibliothek stellt geprüfte Bausteine wie std::vector bereit; rohe Zeiger und manuelle Speicherverwaltung sollten nicht der erste Einstieg sein.", logic:"if/else, for und while steuern Abläufe. Funktionen erhalten typisierte Parameter und liefern einen Rückgabewert. Klassen kapseln Zustand und Verhalten. Moderne C++-Programme nutzen häufig Standardcontainer und RAII, damit Ressourcen über Objektlebenszeiten zuverlässig freigegeben werden.", project:"Baue ein Punkteprogramm mit std::vector, einer Bewertungsfunktion und Tests. CMake verwaltet den Build, Catch2 ist ein Testframework. Die STL meint den Teil der C++-Standardbibliothek mit Containern, Algorithmen und Iteratoren.", basicsTask:"Deklariere int points und std::string name, gib sie mit std::cout aus und achte darauf, dass ein Textliteral in Anführungszeichen steht.", logicTask:"Prüfe die Punkte mit if/else. Ergänze einen Fall für negative Werte und erkläre, warum eine klare Grenze wichtig ist.", projectTask:"Mini-Projekt: Werte mehrere Zahlen in std::vector<int> aus. Trenne die Bewertung in eine Funktion und teste leere sowie gefüllte Eingaben.", check:["Was macht ein C++-Compiler typischerweise?","Er übersetzt C++-Quelltext in ausführbaren Maschinencode.","Er wandelt C++ direkt in eine relationale Tabelle um.","C++ läuft nur in einem Webbrowser."] },
  csharp: { about:"C# ist eine statisch typisierte Sprache im .NET-Ökosystem. Der Compiler übersetzt C# in Intermediate Language; die .NET-Laufzeit führt sie aus. C# wird für Webdienste, Desktopprogramme, Cloudsysteme und mit Unity auch für Spiele verwendet. .NET ist Plattform und Laufzeit, ASP.NET Core ein Webframework.", basics:"Typen wie int, double, bool und string kennzeichnen Werte. var lässt den Compiler den Typ aus dem Ausdruck ableiten; es macht die Variable nicht dynamisch typisiert. Console.WriteLine gibt Text aus. Arrays und List<T> speichern mehrere Werte.", logic:"if/else, Schleifen und Methoden steuern ein Programm. Methoden deklarieren Parameter- und Rückgabetypen. Klassen und Records modellieren eigene Datenformen. Nullable Reference Types helfen, mögliche null-Werte beim Entwickeln sichtbar zu machen.", project:"Erstelle eine kleine Punkteverwaltung mit List<int>, Bewertungsmethode und Tests. xUnit ist ein Testframework. ASP.NET Core stellt HTTP-Endpunkte bereit; lerne erst Typen und Methoden, bevor du Webanfragen darauf aufbaust.", basicsTask:"Lege string name und int points an und gib beide mit Console.WriteLine aus. Ersetze testweise eine Zahl durch Text und beobachte die Typprüfung.", logicTask:"Schreibe eine Methode, die anhand der Punkte eine Meldung liefert, und behandle negative Eingaben ausdrücklich.", projectTask:"Mini-Projekt: Werte eine List<int> aus und schreibe eine Methode mit eindeutigem Rückgabetyp. Formuliere zwei Testfälle für Grenzwerte.", check:["Wofür steht var in C#?","Der Compiler leitet den statischen Typ aus dem Initialwert ab.","Die Variable kann jederzeit jeden beliebigen Typ annehmen.","var startet automatisch eine Webanfrage."] },
  rust: { about:"Rust ist eine kompilierte Sprache für zuverlässige, leistungsfähige Programme. Der Compiler prüft Besitz (ownership), Ausleihen (borrowing) und Lebenszeiten, um viele Speicherfehler vor der Ausführung zu verhindern. Rust wird für Systemsoftware, Kommandozeilenwerkzeuge und Webdienste genutzt. Cargo baut Projekte und verwaltet Abhängigkeiten.", basics:"let bindet einen Namen; Werte sind standardmäßig unveränderlich, mut erlaubt Änderung. Typen wie i32, bool und String beschreiben Werte. String besitzt veränderbaren Text; &str ist eine Textansicht. Option<T> drückt aus, dass ein Wert vorhanden sein kann oder fehlen darf.", logic:"if-Ausdrücke, Schleifen und match steuern Abläufe. Funktionen deklarieren Typen für Parameter und Rückgabe. Vec<T> speichert eine veränderbare Liste. Ownership bestimmt, wer einen Wert besitzt; Referenzen erlauben kontrolliertes Ausleihen ohne unbedachte Kopien.", project:"Baue eine sichere Punkteliste mit Vec<i32>, Ergebnisfunktion und Tests. Cargo verwaltet Build, Test und Abhängigkeiten; Clippy findet häufige Stilprobleme. Axum ist ein Webframework, das erst nach Rust-Grundlagen sinnvoll wird.", basicsTask:"Lege mit let einen Namen und eine Punktzahl an, gib sie mit println! aus und markiere nur den Wert mit mut, den du tatsächlich änderst.", logicTask:"Nutze if/else für die Punktebewertung und ergänze eine Prüfung für einen ungültigen negativen Wert.", projectTask:"Mini-Projekt: Schreibe eine Funktion, die Werte aus Vec<i32> zählt und bewertet. Ergänze Tests für leere Liste und Grenzwerte.", check:["Was prüft Rusts Ownership-System?","Wer Werte besitzt oder ausleiht und ob Zugriffe sicher sind.","Ob eine HTML-Seite die richtige Farbe hat.","Welche Cloudregion ein Programm verwenden muss."] },
  sql: { about:"SQL ist eine deklarative Sprache für relationale Datenbanken. Du beschreibst, welche Daten du erhalten oder ändern möchtest; das Datenbanksystem plant und führt die Abfrage aus. SQL ist nicht wie JavaScript eine allgemeine Sprache für beliebige Programmabläufe. PostgreSQL, SQLite und MySQL haben gemeinsame SQL-Grundlagen, aber auch Dialektunterschiede.", basics:"Eine relationale Datenbank speichert Datensätze in Tabellen mit Spalten. SELECT bestimmt gewünschte Spalten, FROM die Tabelle. WHERE filtert Zeilen, ORDER BY sortiert. NULL bedeutet fehlenden/unbekannten Wert und muss mit IS NULL geprüft werden, nicht mit = NULL.", logic:"GROUP BY fasst Zeilen zusammen; Aggregatfunktionen wie COUNT und SUM berechnen Werte pro Gruppe. JOIN verbindet Tabellen über Beziehungen. INSERT fügt Datensätze hinzu, UPDATE ändert und DELETE entfernt sie. Transaktionen gruppieren Änderungen; gebundene Parameter schützen Anwendungsabfragen vor SQL-Injection.", project:"Entwirf eine kleine Kursdatenbank mit Primärschlüssel und Fremdschlüssel. Schreibe Abfragen mit Filtern, JOIN und Gruppierung und teste Randfälle. Migrationen dokumentieren Schemaänderungen; Indizes können häufige Abfragen beschleunigen, verursachen aber Pflegekosten.", basicsTask:"Führe SELECT title FROM courses aus. Ergänze eine zweite Spalte und erkläre, warum FROM den Tabellennamen benötigt.", logicTask:"Filtere veröffentlichte Kurse mit WHERE und sortiere sie mit ORDER BY. Ergänze eine Gruppierung nach Kategorie mit COUNT.", projectTask:"Mini-Projekt: Entwirf zwei verbundene Tabellen, füge Beispielzeilen ein und schreibe einen JOIN. Verwende in einer Anwendung Platzhalterparameter statt SQL-Stringverkettung.", check:["Wie beschreibt SQL typischerweise eine Abfrage?","Welche Daten gewünscht sind; die Datenbank plant deren Ermittlung.","Jeden einzelnen Maschinenbefehl in Ausführungsreihenfolge.","Das Layout einer Webseite."] },
  c: { about:"C ist eine kompakte, kompilierte Sprache, die häufig für Betriebssysteme, Laufzeitbibliotheken und eingebettete Software verwendet wird. Ein Compiler erzeugt Maschinencode. C gibt Entwicklern viel Kontrolle über Speicher und Datenrepräsentation; diese Kontrolle verlangt sorgfältige Grenzen- und Speicherprüfung.", basics:"Variablen deklarieren Typ und Speicherbedarf, etwa int oder double. printf gibt formatierte Ausgabe aus. Arrays haben feste Länge; Indizes beginnen bei 0. Ein C-String ist ein Zeichenarray mit abschließendem Nullzeichen. Puffergrenzen sind wichtig, um Speicherfehler zu vermeiden.", logic:"if/else und for/while steuern Abläufe; Funktionen strukturieren Arbeit. Zeiger speichern Speicheradressen und müssen korrekt verwendet werden. Headerdateien deklarieren Schnittstellen; .c-Dateien enthalten Implementierungen. Compilerwarnungen sind wertvoll und sollten ernst genommen werden.", project:"Baue ein kleines Programm, das ein begrenztes Array von Punktzahlen auswertet. Kompiliere mit Warnungen und prüfe Grenzwerte. Make automatisiert Builds; Unity (C) ist ein Testframework, nicht die Unity-Spielengine.", basicsTask:"Deklariere int points und gib ihn mit printf und dem passenden Formatbezeichner %d aus.", logicTask:"Schreibe if/else für die Punktebewertung und behandle Werte außerhalb des erwarteten Bereichs.", projectTask:"Mini-Projekt: Werte ein Array fester Länge aus. Prüfe jeden Indexbereich und schreibe eine Funktion, deren Parameter die Anzahl der Werte erhält.", check:["Warum sind Array-Grenzen in C wichtig?","Ein Zugriff außerhalb des Arrays kann undefiniertes Verhalten verursachen.","Weil C Arrays automatisch auf gültige Indizes zurücksetzt.","Weil Arrays in C grundsätzlich keine Werte speichern."] },
  kotlin: { about:"Kotlin ist eine statisch typisierte Sprache, die besonders im Android- und JVM-Umfeld verbreitet ist. Kotlin/JVM wird in JVM-Bytecode übersetzt; Kotlin unterstützt außerdem weitere Ziele. Null-Sicherheit macht mögliche fehlende Werte sichtbarer. Kotlin ist nicht gleich Android: Die Sprache kann auch für Server und andere Anwendungen genutzt werden.", basics:"val bindet einen nicht neu zuweisbaren Namen, var einen veränderbaren. Typen wie Int, String und Boolean werden oft abgeleitet. Nullable-Typen tragen ein ?; sichere Aufrufe wie name?.length vermeiden unbedachte Zugriffe auf null. Listen sind geordnete Sammlungen.", logic:"if ist ein Ausdruck und liefert einen Wert. when wählt zwischen Fällen. Funktionen werden mit fun definiert; Klassen und data class strukturieren eigene Daten. Collections bieten map und filter; Coroutines helfen bei nebenläufiger Arbeit, ersetzen aber nicht das Verständnis von Funktionen und Zuständen.", project:"Baue eine kleine Aufgabenliste mit data class, Liste und einer Funktion zum Filtern. Kotlin Coroutines sind Bibliotheken/Sprachintegration für asynchrone Arbeit; Ktor ist ein Webframework. Android-Apps verwenden heute häufig Kotlin mit Jetpack Compose.", basicsTask:"Lege val name und val points an. Ergänze eine nullable String-Variable und verwende einen sicheren Aufruf mit ?., damit null nicht abstürzt.", logicTask:"Nutze if oder when für die Punktebewertung. Ergänze einen Fall für fehlende Eingabe und erkläre den Unterschied zu 0 Punkten.", projectTask:"Mini-Projekt: Definiere data class Score und eine Funktion, die mehrere Ergebnisse filtert. Teste eine leere Liste und einen fehlenden Namen.", check:["Was bedeutet String? in Kotlin?","Der Wert kann ein String oder null sein.","Der Wert ist immer eine Zahl.","Der Text wird in SQL gespeichert."] },
  swift: { about:"Swift ist eine statisch typisierte, kompilierte Sprache, die Apple für Apps und Systemsoftware entwickelt hat. Sie wird vor allem für iOS, macOS und weitere Apple-Plattformen verwendet, ist aber nicht auf diese beschränkt. SwiftUI ist ein UI-Framework; Swift selbst ist die Sprache.", basics:"let bindet einen nicht neu zuweisbaren Namen; var erlaubt Änderungen. Int, Double, String und Bool sind häufige Typen. Optional-Typen mit ? können nil enthalten. if let entpackt einen vorhandenen Optional-Wert sicher.", logic:"if/switch wählen Fälle; for-in durchläuft Sammlungen. Funktionen erhalten benannte Parameter und deklarierte Rückgabetypen. Structs beschreiben Werttypen, Klassen Referenztypen. Arrays speichern geordnete Werte; Fehler können mit throws und do/catch behandelt werden.", project:"Baue eine kleine Aufgabenliste als Structs und Arrays und prüfe Eingaben. XCTest ist Apples Testframework. SwiftUI baut Oberflächen aus Views; lerne erst Daten, Funktionen und Optionals, bevor du UI-Zustand hinzufügst.", basicsTask:"Lege let name und var points an. Erstelle ein String-Optional und behandle nil mit if let.", logicTask:"Schreibe eine Punktebewertung mit if/else oder switch und ergänze einen Fall für fehlende Werte.", projectTask:"Mini-Projekt: Definiere eine struct Score und eine Funktion, die eine Liste bewertet. Prüfe eine leere Liste und einen Optional-Wert nil.", check:["Was drückt ein Optional String? in Swift aus?","Ein String-Wert oder das Fehlen eines Werts (nil).","Ein String mit garantiert genau einem Zeichen.","Eine Datenbankverbindung."] },
  "web-development": { about:"Webentwicklung verbindet mehrere Technologien: HTML beschreibt Inhalt und Bedeutung, CSS das Aussehen und Layout, JavaScript Interaktion. Browser laden Ressourcen über HTTP(S), bauen aus HTML einen Dokumentbaum und stellen die Seite dar. React ist eine JavaScript-Bibliothek für UI-Komponenten, kein Ersatz für HTML, CSS oder Browsergrundlagen.", basics:"Beginne mit semantischen HTML-Elementen wie main, nav, button und form. CSS-Regeln wählen Elemente und setzen Eigenschaften; Box-Modell, Flexbox und Grid steuern Layout. JavaScript reagiert auf Ereignisse. Jede Technologie hat eine eigene Aufgabe und eigene Syntax.", logic:"Eine Interaktion beginnt mit einem Ereignis, liest oder verändert Daten und aktualisiert die Darstellung. Responsive Layouts passen sich an Bildschirmgrößen an. HTTP-Anfragen laden Daten; bei Formularen sind Labels, Tastaturbedienung und verständliche Fehlermeldungen Teil guter Webarbeit.", project:"Baue eine responsive Projektkarte: semantisches HTML, CSS Grid, eine zugängliche Schaltfläche und eine kleine JavaScript-Interaktion. Prüfe Tastaturbedienung und schmale Fenster. React kann später wiederkehrende UI in Komponenten zerlegen.", basicsTask:"Baue eine HTML-Seite mit main, einer h1 und einem Button. Verwende dann CSS, um Abstand und lesbare Breite festzulegen.", logicTask:"Füge per JavaScript einen click-Listener hinzu, der eine sichtbare Rückmeldung gibt. Achte darauf, dass die Schaltfläche per Tastatur erreichbar bleibt.", projectTask:"Mini-Projekt: Erstelle eine responsive Kartenliste. Trenne HTML-Struktur, CSS-Layout und JavaScript-Verhalten und teste Desktop- sowie Mobilbreite.", check:["Welche Aufgabe hat HTML?","Es beschreibt die Struktur und Bedeutung des Inhalts.","Es führt Datenbankabfragen aus.","Es ersetzt automatisch CSS und JavaScript."] },
  backend: { about:"Ein Backend ist der serverseitige Teil einer Anwendung. Es nimmt HTTP-Anfragen entgegen, prüft Rechte und Eingaben, verarbeitet Regeln und liefert Antworten. Eine API ist der vereinbarte Zugang zu Funktionen und Daten. Node.js ist eine Laufzeit für JavaScript, PostgreSQL eine relationale Datenbank; REST ist ein Architekturstil, kein Framework.", basics:"Eine HTTP-Anfrage enthält Methode, Pfad und möglicherweise Header oder Body. Eine Route ordnet sie einer Funktion zu. Statuscodes beschreiben das Ergebnis (z. B. 200, 400, 401, 404). Eingaben müssen serverseitig validiert werden, auch wenn ein Formular sie im Browser prüft.", logic:"Datenbankzugriffe verwenden parametrisierte Abfragen. Authentifizierung beantwortet, wer jemand ist; Autorisierung, was diese Person darf. Fehler werden kontrolliert behandelt und geben keine Geheimnisse preis. Transaktionen halten zusammengehörige Änderungen konsistent.", project:"Entwirf einen GET-Endpunkt für Kurse: Route, Validierung, begrenzte Datenbankabfrage und JSON-Antwort. OpenAPI dokumentiert Schnittstellen; ein Webframework wie Fastify oder Express verwaltet Routing. Halte Geschäftsregeln getrennt von Transportdetails.", basicsTask:"Beschreibe für GET /api/courses Methode, Pfad, erwartete Antwort und einen passenden Statuscode.", logicTask:"Ergänze eine Eingabeprüfung für eine Kurs-ID und ordne ungültigen, unbekannten und erfolgreichen Fällen passende Statuscodes zu.", projectTask:"Mini-Projekt: Skizziere oder implementiere einen Kurs-Endpunkt mit parametrisierter Datenbankabfrage, Validierung und sicherer Fehlerantwort.", check:["Was ist der Unterschied zwischen Authentifizierung und Autorisierung?","Identität feststellen versus erlaubte Aktionen prüfen.","Beides bedeutet, Daten in HTML umzuwandeln.","Autorisierung prüft nur das Datenbankpasswort."] },
  security: { about:"IT-Sicherheit schützt Systeme, Daten und Menschen vor Missbrauch, Ausfall und unbefugtem Zugriff. Sie ist kein einzelnes Produkt und kein einmaliger Test. Ein Bedrohungsmodell fragt: Was schützen wir, wer könnte es angreifen, über welchen Weg und mit welchen Folgen? Maßnahmen müssen zum tatsächlichen Risiko passen.", basics:"Vertraulichkeit, Integrität und Verfügbarkeit sind grundlegende Schutzziele. Angriffsfläche meint erreichbare Eingänge eines Systems. STRIDE ist ein Modell zum systematischen Sammeln möglicher Bedrohungen; OWASP Top 10 fasst häufige Risiken von Webanwendungen zusammen, aber garantiert keine vollständige Sicherheit.", logic:"Vertraue Eingaben nicht: validiere serverseitig, verwende parametrisierte SQL-Abfragen, sichere Sitzungen und begrenze Rechte. Defense in Depth kombiniert mehrere Schutzschichten. Protokolle helfen bei Erkennung, dürfen aber keine Passwörter oder Tokens enthalten.", project:"Führe für ein kleines Formular ein Bedrohungsmodell durch: schützenswerte Daten, Angreifer, Missbrauchsweg und Maßnahme. Prüfe anschließend Eingabevalidierung, Berechtigungen und Protokollierung. Sichere Standardwerte und Reviews ergänzen automatisierte Scanner.", basicsTask:"Wähle für eine Kursplattform je ein Beispiel für Vertraulichkeit, Integrität und Verfügbarkeit und schreibe dazu eine mögliche Bedrohung.", logicTask:"Prüfe eine Beispielanfrage: Welche Eingabe könnte manipuliert werden, und welche serverseitige Maßnahme reduziert dieses Risiko?", projectTask:"Mini-Projekt: Erstelle ein kleines STRIDE-Bedrohungsmodell für einen Login-Endpunkt und ordne jeder Bedrohung eine konkrete Schutzmaßnahme zu.", check:["Was beschreibt ein Bedrohungsmodell?","Schützenswerte Dinge, mögliche Angreifer, Angriffswege und passende Schutzmaßnahmen.","Eine Liste von Farben für das Loginfenster.","Die Garantie, dass eine Anwendung nie angegriffen wird."] },
  ai: { about:"Künstliche Intelligenz ist ein Sammelbegriff für Verfahren, die Aufgaben wie Erkennen, Vorhersagen oder Textgenerierung unterstützen. Maschinelles Lernen passt Modellparameter anhand von Beispieldaten an. Ein trainiertes Modell macht anschließend Vorhersagen (Inferenz). Ergebnisse sind nicht automatisch Fakten und müssen für den vorgesehenen Zweck bewertet werden.", basics:"Daten enthalten Beispiele und Merkmale. Beim überwachten Lernen gibt es zusätzlich Zielwerte (Labels). Trainingsdaten dienen zum Lernen; getrennte Validierungs- und Testdaten helfen, die Leistung auf unbekannten Beispielen einzuschätzen. Datenqualität, Verzerrungen und Einwilligung beeinflussen das Ergebnis.", logic:"Ein Baseline-Modell liefert einen Vergleich. Metriken wie Genauigkeit passen nicht zu jeder Aufgabe; bei seltenen Ereignissen sind Precision und Recall oft aussagekräftiger. Überanpassung entsteht, wenn ein Modell Trainingsdaten auswendig lernt. Generative Modelle können plausibel klingende, aber falsche Antworten erzeugen.", project:"Definiere für eine kleine Klassifikationsaufgabe Ziel, zulässige Daten, Baseline und Metrik. Trenne Trainings- und Testdaten, dokumentiere Fehler und prüfe Datenschutz. scikit-learn bietet klassische ML-Werkzeuge; PyTorch für neuronale Netze; RAG ergänzt Sprachmodelle um abgerufene Dokumente, garantiert aber keine Korrektheit.", basicsTask:"Unterscheide bei drei Beispielen Eingabemerkmale, gewünschtes Label und mögliche sensible Daten.", logicTask:"Wähle für eine Klassifikation eine geeignete Metrik und erkläre, warum reine Genauigkeit bei stark ungleichen Klassen täuschen kann.", projectTask:"Mini-Projekt: Plane ein kleines Klassifikations-Experiment mit Baseline, getrenntem Testdatensatz und dokumentiertem Fehlerfall. Verwende keine persönlichen Daten.", check:["Was ist Inferenz bei einem trainierten Modell?","Das Modell nutzt gelernte Parameter, um für neue Eingaben eine Ausgabe zu erzeugen.","Das Modell beweist, dass jedes Ergebnis wahr ist.","Das ist das Speichern des Trainingsdatensatzes als SQL-Tabelle."] },
  "game-development": { about:"Spieleentwicklung verbindet Regeln, Eingaben, Zustand, Darstellung, Audio und Tests zu einem interaktiven Programm. Eine Game Loop aktualisiert das Spiel wiederholt und zeichnet den aktuellen Zustand. Engines wie Godot und Unity liefern Werkzeuge, aber ein gutes Spiel beginnt mit einer kleinen klaren Regel und einem spielbaren Prototyp.", basics:"Positionen liegen oft in einem Koordinatensystem; Eingaben ändern den Zustand einer Figur. Bewegung sollte mit verstrichener Zeit (delta time) berechnet werden, damit sie nicht direkt von der Bildrate abhängt. Zustände wie Menü, Spielen und Pause verhindern widersprüchliches Verhalten.", logic:"Kollisionen erkennen Überlappungen oder Kontakt; Physik-Engines simulieren Bewegung, sind aber nicht für jede einfache Regel nötig. Ereignisse trennen Eingabe von Reaktion. Spielschleife: Eingaben lesen, Zustand aktualisieren, Kollisionen prüfen, Bild darstellen.", project:"Baue einen kleinen Sammelgegenstand-Prototyp mit Bewegung, Begrenzungen, Punktestand und Neustart. Teste Steuerung, Kollisionen und Randfälle. Godot nutzt GDScript oder C#; Unity nutzt C#. Die Konzepte gelten unabhängig von der Engine.", basicsTask:"Zeichne die Schritte Eingabe → Zustand → Darstellung und beschreibe, was beim Tastendruck jeweils passiert.", logicTask:"Berechne Bewegung mit Geschwindigkeit mal delta time und erkläre, warum dieselbe Geschwindigkeit bei unterschiedlichen Bildraten gleich bleiben soll.", projectTask:"Mini-Projekt: Skizziere oder baue ein Sammelspiel mit Bewegung, Spielfeldgrenze, Punktestand und einer klaren Gewinnbedingung.", check:["Warum nutzt eine Game Loop delta time?","Damit Bewegung möglichst unabhängig von der Bildrate bleibt.","Damit der Spieler ohne Eingabe automatisch gewinnt.","Damit der Code in eine Datenbank geschrieben wird."] },
  career: { about:"Der Weg in einen Entwicklerjob besteht nicht nur aus einer bestimmten Programmiersprache. Wichtig sind Grundlagen, problemlösendes Arbeiten, lesbarer Code, Zusammenarbeit und ein glaubwürdiger Nachweis eigener Projekte. Anforderungen variieren je nach Rolle, Team und Region; Stellenanzeigen sind eine bessere Orientierung als pauschale Versprechen.", basics:"Ein Portfolio erklärt für wen ein Projekt gedacht ist, welches Problem es löst, welche Entscheidungen du getroffen hast und was du gelernt hast. Git speichert nachvollziehbare Änderungen; ein Repository enthält Dateien und Historie. Ein README erklärt Start, Zweck und Grenzen des Projekts.", logic:"Ein Code Review prüft Lesbarkeit, Korrektheit, Tests und Risiken, nicht den Wert einer Person. Issues und kleine Commits machen Arbeit nachvollziehbar. Im Gespräch hilft die STAR-Methode, eine konkrete Erfahrung strukturiert zu schildern; sie ersetzt keine ehrliche technische Erklärung.", project:"Wähle ein kleines Projekt, mache es ausführbar, schreibe Tests für zentrale Regeln und dokumentiere Installation und bekannte Grenzen. Entferne Zugangsdaten und persönliche Daten. Übe, eine Designentscheidung und einen Fehlerfall verständlich zu erklären.", basicsTask:"Schreibe für ein eigenes oder Demo-Projekt Zielgruppe, Problem, Lösung und eine konkrete Designentscheidung auf.", logicTask:"Formuliere eine kleine Änderung als Issue und einen verständlichen Commit-Titel. Prüfe, ob jemand anderes die Änderung nachverfolgen kann.", projectTask:"Mini-Projekt: Erstelle eine Portfolio-README mit Problem, Screenshots/Ergebnis, Startanleitung, eingesetzten Werkzeugen und einem Abschnitt zu Grenzen und nächsten Schritten.", check:["Was macht ein gutes Portfolio-Projekt nachvollziehbar?","Problem, Zielgruppe, Entscheidungen, Ergebnis und Startanleitung.","Nur eine lange Liste von Framework-Namen.","Eine Behauptung, jede Technologie perfekt zu beherrschen."] },
};

