function buildCourse(definition: typeof courseDefinitions[number]): LearningCourse {
  const teaching = courseTeaching[definition.id];
  if (!teaching) throw new Error(`Kursinhalt fehlt: ${definition.id}`);
  const markers = courseMarkers[definition.id];
  const stageNames = topicLessonTitles[definition.id] ?? ["Grundlagen: Werte und Syntax", "Kontrollfluss und Daten", "Funktionen und Mini-Projekt"];
  return { id: definition.id, version:"1.0.0", title:definition.title, category:definition.category, lessons: lessonStages.map((stage, index) => {
    const exampleIndex = Math.max(0, index - 1);
    const exampleCode = index === 0 ? `${definition.title}: ${definition.topic}` : index === 3
      ? `${definition.examples[2].replaceAll("\\n", "\n")}\n\n// Weiterer Baustein / Projektidee\n${definition.examples[3].replaceAll("\\n", "\n")}`
      : definition.examples[exampleIndex].replaceAll("\\n", "\n");
    const explanation = index === 0 ? teaching.about : index === 1 ? teaching.basics : index === 2 ? teaching.logic : teaching.project;
    const task = index === 0 ? teaching.check[0] : index === 1 ? teaching.basicsTask : index === 2 ? teaching.logicTask : teaching.projectTask;
    const knowledgeCheck = index === 0 ? { question: teaching.check[0], options: [teaching.check[1], teaching.check[2], teaching.check[3]], correctIndex: 0, explanation: teaching.check[1] } : undefined;
    const marker = index === 0 ? "" : markers[index - 1];
    return {
      id:`${definition.id}-${stage.id}`, title:index === 0 ? `Was ist ${definition.title} und wofür nutzt man es?` : stageNames[index - 1], objective:index === 0 ? `Du kannst erklären, wofür ${definition.title} verwendet wird und in welcher Umgebung es arbeitet.` : stage.objective, duration:index === 0 ? 10 : index === 3 ? 25 : 20, language:definition.id === "web-development" ? ["html", "html", "css", "javascript"][index] : definition.language,
      concepts:[{tag:index === 0 ? "Einordnung" : definition.title,description:teaching.about},{tag:stage.method.title,description:stage.method.description}],
      explanation,
      starterCode:index === 0 ? "" : `// ${stageNames[index - 1]}\n// Lies die Aufgabe und ergänze den passenden Baustein.\n`, exampleCode:index === 0 ? undefined : exampleCode,
      task,
      successPattern:marker ? new RegExp(marker,"i") : /(?!) /,
      practice:index !== 0, knowledgeCheck, visualSteps:stage.visual,
      method:stage.method,
      framework:{title:definition.framework,description:`Einordnung: ${ecosystemDescriptions[definition.id]} Lerne zuerst die Sprach- und Fachgrundlagen; dann kannst du einschätzen, welche Teile das Werkzeug übernimmt und welche Entscheidungen weiter bei dir liegen.`},
    };
  }) };
}

export const learningCourses: LearningCourse[] = [programmingCourse, ...courseDefinitions.map(buildCourse)];
export function getLearningCourse(courseId: string): LearningCourse { return learningCourses.find((course) => course.id === courseId) ?? programmingCourse; }
